parameters.jsCode:
const body = $json.body ?? {};

const question = String(body.question ?? "").trim();

if (!question) {
  throw new Error("Question is required.");
}

return [
  {
    json: {
      question,
      user_id: body.user_id ?? null,
      user_email: body.user_email ?? null,
    },
  },
];

parameters.jsonQuery:
={{
JSON.stringify((() => {
  const p = {};

  const origin = $fromAI(
    'origin',
    'Departure city/origin requested by the passenger. Return empty string if not specified.',
    'string'
  );

  const destination = $fromAI(
    'destination',
    'Destination city requested by the passenger. Return empty string if not specified.',
    'string'
  );

  const departureDate = $fromAI(
    'departure_date',
    'Departure date requested by passenger in YYYY-MM-DD format. Return empty string if not specified.',
    'string'
  );

  const cabin = $fromAI(
    'cabin',
    'Cabin class requested by passenger. Return empty string if not specified.',
    'string'
  );

  const maxPrice = $fromAI(
    'max_price',
    'Maximum price requested by passenger. Return empty string if not specified.',
    'string'
  );

  const flightNumber = $fromAI(
    'flight_number',
    'Flight number requested by passenger. Return empty string if not specified.',
    'string'
  );

  if (origin) p.origin = origin;
  if (destination) p.destination = destination;
  if (departureDate) p.departure_date = departureDate;
  if (cabin) p.cabin = cabin;
  if (maxPrice) p.max_price = Number(maxPrice);
  if (flightNumber) p.flight_number = flightNumber;

  return p;
})())
}}
